 <script>document.querySelectorAll('[data-slot-select]').forEach(sel=>sel.addEventListener('change',()=>{const o=sel.selectedOptions[0];if(o&&o.value!=='0'){const f=sel.closest('form');f.querySelector('[name=booking_date]').value=o.dataset.date;f.querySelector('[name=booking_time]').value=o.dataset.time;}}));</script><?php include __DIR__.'/includes/footer.php';exit;
