$q=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$area=trim((string)($_GET['area']??''));$sort=(string)($_GET['sort']??'featured');$page=max(1,(int)($_GET['page']??1));$perPage=9;
$where=["l.status='published'"];$params=[];if($q!==''){$where[]='(l.name LIKE :q OR l.description LIKE :q OR l.location LIKE :q OR l.city LIKE :q OR l.tags LIKE :q)';$params[':q']='%'.$q.'%';}if($area!==''){$where[]='(l.location LIKE :area OR l.city LIKE :area)';$params[':area']='%'.$area.'%';}if($category!==''&&in_array($category,categories(),true)){$where[]='l.category=:category';$params[':category']=$category;}
$w=implode(' AND ',$where);$cs=db()->prepare('SELECT COUNT(*) FROM listings l WHERE '.$w);$cs->execute($params);$total=(int)$cs->fetchColumn();record_search($q!==''?$q:$category,$area,$total);
$order=match($sort){'name'=>'l.name COLLATE NOCASE ASC','newest'=>'l.created_at DESC','reviews'=>"(SELECT COUNT(*) FROM reviews r WHERE r.listing_id=l.id AND r.status='approved') DESC,l.name ASC",default=>'l.sponsored DESC,l.featured DESC,l.name COLLATE NOCASE ASC'};
$st=db()->prepare('SELECT l.* FROM listings l WHERE '.$w.' ORDER BY '.$order.' LIMIT :lim OFFSET :off');foreach($params as $k=>$v)$st->bindValue($k,$v);$st->bindValue(':lim',$perPage,PDO::PARAM_INT);$st->bindValue(':off',($page-1)*$perPage,PDO::PARAM_INT);$st->execute();$listings=$st->fetchAll();$fs=db()->query("SELECT * FROM listings WHERE status='published' AND featured=1 ORDER BY sponsored DESC,created_at DESC LIMIT 3");$featuredListings=$fs->fetchAll();
$homeStats=['places'=>(int)db()->query("SELECT COUNT(*) FROM listings WHERE status='published'")->fetchColumn(),'reviews'=>(int)db()->query("SELECT COUNT(*) FROM reviews WHERE status='approved'")->fetchColumn(),'cities'=>(int)db()->query("SELECT COUNT(DISTINCT city) FROM listings WHERE status='published' AND city<>''")->fetchColumn()];$cityBrowse=db()->query("SELECT city,COUNT(*) total FROM listings WHERE status='published' AND city<>'' GROUP BY city ORDER BY total DESC,city LIMIT 8")->fetchAll();$pageTitle=setting('site_name','LocalGuide').' | '.setting('site_tagline','Discover more. Experience better.');$pageDescription=setting('site_description','Discover the best of your neighbourhood.');$canonicalUrl=app_url('index.php');include __DIR__.'/includes/header.php';
