<script>
(()=>{const voice=document.getElementById('voiceSearch'),input=document.getElementById('globalSearch'),status=document.getElementById('voiceSearchStatus');if(!voice||!input)return;const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){voice.hidden=true;return;}voice.addEventListener('click',()=>{const rec=new SpeechRecognition();rec.lang=(document.documentElement.lang==='bn'?'bn-IN':document.documentElement.lang==='hi'?'hi-IN':'en-IN');rec.interimResults=false;rec.maxAlternatives=1;status.textContent='Listening… speak your search';voice.classList.add('is-listening');rec.onresult=e=>{input.value=e.results[0][0].transcript;status.textContent='Search captured. Press Explore to see matches.';input.focus();};rec.onerror=()=>{status.textContent='Voice search was unavailable. You can type your search instead.';};rec.onend=()=>voice.classList.remove('is-listening');rec.start();});})();
</script>
